effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    vec2 g = acScreenNorm * density;
    vec2 cell = floor(g);
    vec2 f = fract(g) - 0.5;

    float r = hash21(cell);
    float r2 = hash21(cell + 13.7);
    float fase = r * 6.2831853;
    float piscar = 0.5 + 0.5 * sin(acTime * speed + fase);
    vec2 pos = (vec2(r, r2) - 0.5) * 0.6;
    float d = length(f - pos);
    float ponto = smoothstep(0.32 * size, 0.0, d) * piscar;

    // só onde a camada já está brilhante
    float l = dot(orig.rgb, LUMA);
    float onde = smoothstep(threshold, threshold + 0.2, l);

    vec3 cor = orig.rgb + tint.rgb * tint.a * ponto * onde * 1.5;
    fragColor = vec4(cor, orig.a);
}
